-- Admission requirements for 9 schools that earlier waves could not read (checked 14 Nov 2026 from official pages). Only fills schools that have none yet.
update schools set admission_info = $q${"english": "Curtin accepts IELTS Academic overall 6.5 with 6.0 in each part. TOEFL iBT needs 81 overall for tests taken from June 2026 (79 before). PTE needs 58 overall. The page lists a WASSCE pass only for Nigeria (C6 or better in English, within five years), not Ghana.", "how_to_apply": "Apply online. Gather certified documents, prove English, create an account in the application portal and choose up to five courses (only the first is assessed unless you miss its entry requirements). If you accept an offer you get a Confirmation of Enrolment for your student visa.", "documents": "Certified copies of all transcripts, grading descriptions and award certificates (every page). English test result and passport photo page. Documents not in English need an official translation from an accredited translator. Translations by you or an agent are not accepted.", "deadlines": "The page links to a separate key dates page. No dates were on the pages read.", "sources": ["https://www.curtin.edu.au/study/applying/international/applying-via-curtin/", "https://www.curtin.edu.au/study/applying/international/required-application-documents/", "https://www.curtin.edu.au/study/applying/english-language-requirements/accepted-english-qualifications/"]}$q$::jsonb, admission_link = $q$https://www.curtin.edu.au/study/applying/international/applying-via-curtin/$q$, admission_checked = '2026-11-14' where id = 'ad5908a3-fb1f-4887-8f6b-9c51aac03b0a' and admission_info is null;
update schools set admission_info = $q${"ug": "You need to meet the course's academic entry, prerequisite subjects and English requirements. Some courses also ask for a folio, personal statement or interview. Direct entry needs Year 12 or an equivalent overseas qualification. The pages read do not mention Ghana or WASSCE.", "english": "English proficiency must be met. No scores were on the pages read.", "how_to_apply": "Check your course's requirements, then apply through the international application route on the page. Applicants from some listed countries must use a registered Monash agent. Credit for prior study must be requested before you enrol. Monash Foundation Year is a pre-university program for international students that guarantees entry to first year of a Monash degree if you pass it and meet the other requirements.", "deadlines": "International students can apply at any time of year. Teaching starts in early March (semester 1) and mid-July (semester 2).", "sources": ["https://www.monash.edu/admissions/apply/international-ug", "https://www.monash.edu/study/courses/entry-requirements", "https://www.monash.edu/study/courses/entry-pathways-international"]}$q$::jsonb, admission_link = $q$https://www.monash.edu/admissions/apply/international-ug$q$, admission_checked = '2026-11-14' where id = '4551d6e0-f607-4048-9a1c-626663fad4d7' and admission_info is null;
update schools set admission_info = $q${"ug": "Eligibility depends on the course and your qualification from your country of study. The pages read do not say whether WASSCE is accepted.", "english": "IELTS Academic 6.0 overall with no band below 5.5, or TOEFL iBT 79 (writing at least 22), or PTE Academic 57 with no skill below 50. Scores must be from the last two years. Some courses need higher scores. UNE can also accept one year of full-time study in English in the last five years, or its English for Academic Purposes course.", "how_to_apply": "Apply online through the UNE application portal or an authorised UNE agent.", "deadlines": "Trimester 1 (starts February): apply by end of November. Trimester 2 (starts June): apply by end of May. Late applications are considered where possible.", "documents": "Certified copies of transcripts and proof of completion, passport photo page or other birth record, and evidence of English. Documents not in English need an officially certified English translation.", "sources": ["https://www.une.edu.au/international/apply", "https://www.une.edu.au/international/apply/eligibility/english-language-requirements"]}$q$::jsonb, admission_link = $q$https://www.une.edu.au/international/apply$q$, admission_checked = '2026-11-14' where id = '524eccdb-dee6-4428-9c76-010546907c50' and admission_info is null;
update schools set admission_info = $q${"ug": "You must be an international student, at least 18 when the program starts, and meet the program's admission requirements and English requirements. Undergraduate requirements are listed on each program page.", "english": "Accepted: IELTS, TOEFL, or other recognised test. You can instead give a letter from your school confirming all classes were taught and examined in English, with proof you finished within the last five years. IELTS entry level shown is 6.0 overall with 5.5 in each band.", "how_to_apply": "Apply through the UniSC international application portal, or through a registered UniSC agent (required for some regions).", "documents": "Certified copies of all qualifications and an official transcript of all subjects (exam slips and term report cards are not accepted), graduation certificate if completed, English evidence, and passport photo page. Every page must be certified. Documents not in English need a certified translation.", "fees_link": "https://www.unisc.edu.au/international/programs-and-fees", "deadlines": "No dates on the pages read. The page points to the academic calendar.", "sources": ["https://www.unisc.edu.au/international/how-to-apply", "https://editcd.unisc.edu.au/international/how-to-apply/supporting-documents"]}$q$::jsonb, admission_link = $q$https://www.unisc.edu.au/international/how-to-apply$q$, admission_checked = '2026-11-14' where id = '20a424cf-dc55-400e-94ef-bd6a16432f36' and admission_info is null;
update schools set admission_info = $q${"ug": "Most OU courses are open entry, so no set qualifications are needed. Requirements for particular courses are on each course or module page.", "how_to_apply": "Follow the OU's ten steps to starting study. Fees and funding are shown on each qualification or module page. If you plan to use an OU qualification for work or study abroad, check it meets local requirements first.", "sources": ["https://www.open.ac.uk/courses/registration-info"]}$q$::jsonb, admission_link = $q$https://www.open.ac.uk/courses/registration-info$q$, admission_checked = '2026-11-14' where id = '9ceb568a-5e21-4809-a8a9-8aebfefb690c' and admission_info is null;
update schools set admission_info = $q${"ug": "For Ghana, WASSCE alone is not enough. Cambridge strongly recommends further study. Suitable options are A Levels, the IB, 5 or more AP tests at score 5 plus A1 in every WASSCE subject, or possibly a first year of a degree at a non-UK university. If you plan to use APs with WASSCE or a first year of university, contact your shortlisted Colleges. Requirements shown are for 2027 entry.", "english": "Applicants from a country that is not majority English-speaking must meet the English language requirements.", "how_to_apply": "All applicants apply through UCAS. Offers are made before final results and confirmed once results arrive.", "application_fee": "Most international applicants pay 60 pounds. Applicants from a listed group of countries are exempt, and Ghana is not on that list.", "sources": ["https://www.undergraduate.study.cam.ac.uk/international-students/international-applications", "https://www.undergraduate.study.cam.ac.uk/international-students/international-entry-requirements"]}$q$::jsonb, admission_link = $q$https://www.undergraduate.study.cam.ac.uk/international-students/international-applications$q$, admission_checked = '2026-11-14' where id = '48ea74c8-a747-4f8e-a065-25fdfb2bc532' and admission_info is null;
update schools set admission_info = $q${"english": "You must show English proficiency. Accepted evidence includes a test certificate, a letter from your school or university confirming you were taught in English, or an employer letter confirming 18 months of substantial English use. Exact scores are on the programme page.", "how_to_apply": "Apply online on the programme page. Create an account, upload your documents, sign the declaration and pay the fee if the course has one. You get a student reference number by email within 24 hours.", "deadlines": "Apply early. The final date is on each programme page.", "application_fee": "Some programmes charge a non-refundable fee. The amount is on the programme page.", "documents": "ID showing full name and date of birth, scans of all qualifications on your application, English evidence, and references and a CV if you apply on work experience. You can upload later by emailing documents@london.ac.uk. You arrange any translations yourself.", "sources": ["https://www.london.ac.uk/study/how-apply/undergraduate-applications", "https://www.london.ac.uk/sites/default/files/leaflets/undergraduate-applications-guidance.pdf"]}$q$::jsonb, admission_link = $q$https://www.london.ac.uk/study/how-apply/undergraduate-applications$q$, admission_checked = '2026-11-14' where id = '1fdba734-8ef7-4cae-997b-99b398b3f30f' and admission_info is null;
update schools set admission_info = $q${"ug": "You must meet your course's requirements. Oxford accepts a wide range of UK and international qualifications. The pages read do not mention Ghana or WASSCE, so check the course page and the applicant guide.", "english": "IELTS Academic overall 7.5 with at least 7.0 in each part is recommended. Also accepted: C1 Advanced or C2 Proficiency (191 overall, 185 each part). Not accepted: PTE Academic Online, TOEFL Essentials, TOEFL ITP. Proof is due by 31 July in the year of your offer.", "how_to_apply": "Apply through UCAS. Choose a course, choose a college or make an open application, and read the applicant guide.", "deadlines": "15 October for competitive applications.", "sources": ["https://www.ox.ac.uk/admissions/undergraduate/applying/for-international-students", "https://ox.ac.uk/admissions/undergraduate/applying-to-oxford/for-international-students/english-language-requirements?wssl=1", "https://www.ox.ac.uk/admissions/undergraduate/applying-to-oxford"]}$q$::jsonb, admission_link = $q$https://www.ox.ac.uk/admissions/undergraduate/applying/for-international-students$q$, admission_checked = '2026-11-14' where id = 'a6eaa4c7-f554-438c-bdff-44599747e72f' and admission_info is null;
update schools set admission_info = $q${"ug": "The UCO admission page read covers US applicants. Freshman standard: 2.7 GPA with top 50% class rank, or ACT 20, or SAT 1030. ACT/SAT are optional under a test-optional pilot through Spring 2026. International-specific rules were not on this page.", "application_fee": "A non-refundable application fee is paid on submission. The amount is not listed on this page.", "documents": "Application, official high school transcript or GED, official transcripts from every college attended, and proof of citizenship if applicable.", "deadlines": "Not on this page. It points to the Apply to UCO site, or Broncho OneStop on 405-974-2727.", "sources": ["https://uco.teamdynamix.com/TDClient/2558/OneStopPortal/KB/ArticleDet?ID=112593"]}$q$::jsonb, admission_link = $q$https://www.uco.edu/students/oga/future-students/undergraduate-admissions$q$, admission_checked = '2026-11-14' where id = 'ddbd10c6-0131-413d-822c-d6a893207ec5' and admission_info is null;
